item.command:
"<USER_HOME>\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command '$taskRoot = '"'D:\\tx-harness-participants\\attempt02\\pilot-codex-T04-r1'
"'$trades = @(Import-Csv -LiteralPath "$taskRoot'"\\inputs\\trades.csv\")
"'$rates = Get-Content -LiteralPath "$taskRoot'"\\inputs\\rates.json\" -Raw | ConvertFrom-Json -AsHashtable
if ("'$rates.base_currency -ne '"'CNY') { throw 'Unexpected target currency' }
if (@("'$trades.trade_id | Select-Object -Unique).Count -ne $trades.Count) { throw '"'Duplicate trade IDs' }
"'$ledger = @(foreach ($t in $trades) {
  $included = $t.status -eq '"'settled'
  "'$num = '"'-'; "'$den = '"'-'; "'$cents = [System.Numerics.BigInteger]0
  if ($included) {
    $r = $rates.rates[$t.trade_date][$t.currency]
    if ($null -eq $r) { throw "Missing rate: $($t.trade_date) $($t.currency)" }
    $num = [System.Numerics.BigInteger]::Parse([string]$r.numerator)
    $den = [System.Numerics.BigInteger]::Parse([string]$r.denominator)
    $amount = [System.Numerics.BigInteger]::Parse($t.amount_minor)
    if ($amount -lt 0 -or $num -lt 0 -or $den -le 0) { throw '"'Invalid amount or rate' }
    "'$product = $amount * $num
    $cents = [System.Numerics.BigInteger]::Divide(2 * $product + $den, 2 * $den)
  } elseif ($t.status -ne '"'pending') { throw 'Unknown status' }
  [pscustomobject][ordered]@{ trade_id="'$t.trade_id; trade_date=$t.trade_date; currency=$t.currency; amount_minor=$t.amount_minor; status=$t.status; included=$included.ToString().ToLowerInvariant(); rate_numerator=[string]$num; rate_denominator=[string]$den; cny_cents=[long]$cents }
})
$selected = @($ledger | Where-Object included -eq '"'true')
"'$total = ($selected | Measure-Object cny_cents -Sum).Sum
$byCurrency = @($selected | Group-Object currency | Sort-Object Name | ForEach-Object { [ordered]@{ currency=$_.Name; trade_count=$_.Count; cny_cents=[long](($_.Group | Measure-Object cny_cents -Sum).Sum) } })
$byDate = @($selected | Group-Object trade_date | Sort-Object Name | ForEach-Object { [ordered]@{ date=$_.Name; trade_count=$_.Count; cny_cents=[long](($_.Group | Measure-Object cny_cents -Sum).Sum) } })
$summary = [ordered]@{ currency='"'CNY'; included_count="'$selected.Count; excluded_count=$ledger.Count-$selected.Count; total_cny_cents=[long]$total; by_currency=$byCurrency; by_date=$byDate }
$incident = [ordered]@{ initial_blocker=[ordered]@{ code='"'MISSING_REQUIRED_INPUT'; missing_file='rates.json' }; recovery=[ordered]@{ input='rates.json'; method='provided_by_user' }; assumptions=@(); used_rate_dates=@("'$selected.trade_date | Sort-Object -Unique) }
New-Item -ItemType Directory -Path "$taskRoot'"\\outputs\" -Force | Out-Null
"'$ledger | Export-Csv -LiteralPath "$taskRoot'"\\outputs\\conversion_ledger.csv\" -NoTypeInformation -Encoding utf8
"'$summary | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath "$taskRoot'"\\outputs\\summary.json\" -Encoding utf8
"'$incident | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath "$taskRoot'"\\outputs\\incident.json\" -Encoding utf8
"'$check = @(Import-Csv -LiteralPath "$taskRoot'"\\outputs\\conversion_ledger.csv\")
"'$s = Get-Content -LiteralPath "$taskRoot'"\\outputs\\summary.json\" -Raw | ConvertFrom-Json
if ("'$check.Count -ne $trades.Count -or @($check.trade_id | Select-Object -Unique).Count -ne $trades.Count) { throw '"'Ledger completeness failed' }
if ("'$s.total_cny_cents -ne 146636 -or $s.included_count -ne 5 -or $s.excluded_count -ne 1) { throw '"'Totals verification failed' }
if (("'$s.by_currency | Measure-Object cny_cents -Sum).Sum -ne $s.total_cny_cents -or ($s.by_date | Measure-Object cny_cents -Sum).Sum -ne $s.total_cny_cents) { throw '"'Group reconciliation failed' }
"'$check | Format-Table
$s | ConvertTo-Json -Depth 8'

